import {useState} from 'react';
import {AlertTriangle,ArrowRight,ArrowUpRight,CalendarDays,CheckCircle2,ChevronRight,ClipboardList,Clock3,FileClock,Plus,RefreshCw,UsersRound} from 'lucide-react';
import {buildDashboardIntelligence} from '../../lib/externalDashboardIntelligence';
import {Button,FeedbackState,FilterBar,LoadingSkeleton,PageHeader,SectionHeader,StatusChip,Surface} from './ui/ExternalUI';

const KPI=[['Active clients','activeClients',UsersRound,'clients','clients'],['New this month','newClientsThisMonth',ArrowUpRight,'clients','clients'],['Consultations this week','consultationsThisWeek',CalendarDays,'consultations','consultations'],['Follow-ups due today','followupsDueToday',FileClock,'followups','followups'],['Overdue follow-ups','overdueFollowups',Clock3,'followups','followups'],['Overdue tasks','overdueTasks',ClipboardList,'tasks','tasks'],['Onboarding completed','onboardingCompleted',CheckCircle2,'clients','onboarding'],['Clients needing review','clientsNeedingReview',AlertTriangle,'attention','attention']];
const SEVERITY={P1_CRITICAL:{tone:'critical',label:'P1 Critical',accent:'border-l-red-700'},P2_HIGH:{tone:'dangerTone',label:'P2 High',accent:'border-l-orange-600'},P3_MEDIUM:{tone:'warning',label:'P3 Medium',accent:'border-l-amber-500'},P4_LOW:{tone:'info',label:'P4 Low',accent:'border-l-blue-600'}};
const FILTERS=['All','Critical','High','Medium','Low','Overdue','Onboarding','Follow-ups','Tasks','Goals'];

function KpiCard({label,value,Icon,unavailable,onClick}){return <button onClick={onClick} className="group min-h-[112px] rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-[0_1px_2px_rgba(15,23,42,.04)] transition hover:border-slate-300 hover:shadow-[0_5px_18px_rgba(15,23,42,.07)]"><span className="flex items-start justify-between gap-3"><span className="text-xs font-medium leading-5 text-slate-500">{label}</span><Icon aria-hidden="true" size={16} className="mt-0.5 text-slate-400 transition group-hover:text-blue-700"/></span><strong className="mt-4 block text-[1.75rem] font-semibold leading-none tracking-[-.04em] text-slate-950">{unavailable?'—':value}</strong><span className={`mt-2 block text-[11px] ${unavailable?'text-amber-700':'text-slate-400'}`}>{unavailable?'Source unavailable':'View details'}</span></button>}

function Distribution({title,question,data,unavailable}){const entries=Object.entries(data).filter(([,value])=>value>0);const total=entries.reduce((sum,[,value])=>sum+value,0);const colours=['bg-blue-600','bg-emerald-600','bg-amber-500','bg-slate-400'];return <Surface density="standard"><SectionHeader title={title} subtitle={question}/>{unavailable?<FeedbackState kind="error" title={`${title} unavailable`} copy="The source request failed. No zero or empty result is inferred."/>:total?<><div aria-label={`${title} distribution`} className="mt-5 flex h-2 overflow-hidden rounded-full bg-slate-100">{entries.map(([label,value],index)=><span key={label} title={`${label}: ${value}`} style={{width:`${value/total*100}%`}} className={colours[index%colours.length]}/>)}</div><dl className="mt-4 grid gap-2">{entries.map(([label,value],index)=><div key={label} className="flex items-center justify-between gap-3 text-xs"><dt className="flex items-center gap-2 text-slate-600"><span className={`h-2 w-2 rounded-full ${colours[index%colours.length]}`}/>{label.replaceAll('_',' ')}</dt><dd className="font-semibold text-slate-950">{value}</dd></div>)}</dl></>:<FeedbackState title="No confirmed data" copy="There are no source records in this distribution yet."/>}</Surface>}

function matchesFilter(item,filter){if(filter==='All')return true;if(filter==='Critical')return item.level==='P1_CRITICAL';if(filter==='High')return item.level==='P2_HIGH';if(filter==='Medium')return item.level==='P3_MEDIUM';if(filter==='Low')return item.level==='P4_LOW';if(filter==='Overdue')return item.signal.includes('OVERDUE');return item.signal.startsWith(filter.toUpperCase().replace('-','_').replace('FOLLOW_UPS','FOLLOW_UP'))}

function PriorityInbox({items,onNavigate,onOpen}){const [filter,setFilter]=useState('All');const visible=items.filter(item=>matchesFilter(item,filter));return <Surface id="needs-attention" density="standard" className="min-w-0 border-slate-300 shadow-[0_8px_28px_rgba(15,23,42,.07)] sm:p-6"><SectionHeader title="Needs attention" subtitle="Deterministic operational signals—not clinical risk." actions={<StatusChip tone={items.length?'warning':'success'} icon={items.length?AlertTriangle:CheckCircle2}>{items.length} open</StatusChip>}/><FilterBar label="Priority filters"><div className="mt-4 flex max-w-full gap-1.5 overflow-x-auto pb-1">{FILTERS.map(item=><button key={item} onClick={()=>setFilter(item)} aria-pressed={filter===item} className={`min-h-11 shrink-0 rounded-lg border px-3 text-xs font-medium ${filter===item?'border-slate-900 bg-slate-900 text-white':'border-slate-200 bg-white text-slate-600 hover:bg-slate-50'}`}>{item}</button>)}</div></FilterBar><div className="mt-4 divide-y divide-slate-100 border-y border-slate-100">{visible.slice(0,8).map(item=>{const severity=SEVERITY[item.level]||SEVERITY.P4_LOW;return <button key={item.key} onClick={()=>item.target==='client'&&item.client?onOpen(item.client):onNavigate(item.target)} className={`grid min-h-[88px] w-full gap-3 border-l-2 px-3 py-4 text-left transition hover:bg-slate-50 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-center sm:px-4 ${severity.accent}`}><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><strong className="truncate text-sm font-semibold text-slate-950">{item.client?.displayName||'Practice task'}</strong><StatusChip tone={severity.tone} icon={item.level==='P1_CRITICAL'?AlertTriangle:undefined}>{severity.label}</StatusChip></div><p className="mt-1.5 text-sm leading-5 text-slate-700">{item.reason}</p><p className="mt-1 text-xs text-slate-500">{item.age} · {item.signal.replaceAll('_',' ')}</p></div><span className="flex items-center text-xs font-semibold text-blue-700">{item.action}<ChevronRight aria-hidden="true" className="ml-1" size={15}/></span></button>})}</div>{!visible.length&&<FeedbackState title={items.length?'No priorities match this filter':'No confirmed priorities'} copy={items.length?'Choose another filter to see active work.':'The active queue is clear based on loaded source records.'}/>}</Surface>}

function Agenda({items,onNavigate}){return <Surface density="standard"><SectionHeader title="Today & upcoming" subtitle="Your next scheduled practice events." actions={<Button variant="ghost" onClick={()=>onNavigate('calendar')}>Open calendar <ArrowRight size={14}/></Button>}/>{items.length?<div className="mt-4 divide-y divide-slate-100">{items.map(item=><article key={item.id} className="grid grid-cols-[4.5rem_1fr] gap-3 py-3"><time className="text-xs font-semibold text-blue-700">{new Date(item.due_at).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}</time><div><p className="text-sm font-semibold text-slate-900">{item.title}</p><p className="mt-1 text-xs text-slate-500">{new Date(item.due_at).toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})} · {item.status?.replaceAll('_',' ')||'Scheduled'}</p></div></article>)}</div>:<FeedbackState title="A clear schedule" copy="No upcoming consultations are confirmed in the loaded period."/>}</Surface>}

function RecentActivity({items}){return <Surface density="standard"><SectionHeader title="Recent activity" subtitle="Latest confirmed practice notifications."/>{items.length?<ol className="mt-4 space-y-4">{items.map(item=><li key={item.id} className="relative border-l border-slate-200 pl-4 before:absolute before:-left-1 before:top-1 before:h-2 before:w-2 before:rounded-full before:bg-blue-600"><p className="text-sm font-medium text-slate-900">{item.title}</p><time className="mt-1 block text-xs text-slate-500">{new Date(item.created_at).toLocaleString()}</time></li>)}</ol>:<FeedbackState title="No recent activity" copy="No notification activity is confirmed for this period."/>}</Surface>}

export function ExternalIntelligentHome({clients,user,data,state,error,onRetry,onAdd,onNavigate,onOpen}){if(state==='loading')return <div aria-label="Loading dashboard intelligence" className="space-y-5"><LoadingSkeleton height="7rem"/><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{Array.from({length:8},(_,i)=><LoadingSkeleton key={i} height="7rem" label="Loading KPI"/>)}</div><LoadingSkeleton height="22rem" label="Loading priority inbox"/></div>;if(state==='error')return <Surface><FeedbackState kind="error" title="Dashboard intelligence unavailable" copy={`${error}. Client records are not presented as empty.`} action={<Button icon={RefreshCw} onClick={onRetry}>Retry</Button>}/></Surface>;
  const model=buildDashboardIntelligence({clients,resources:data.resources,notifications:data.notifications});
  return <div className="space-y-6 pb-24 lg:pb-8"><PageHeader eyebrow={new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} title={`Today, ${(user?.name||'Consultant').split(' ')[0]}`} subtitle="Your factual practice priorities, schedule and progress in one place." actions={<><Button variant="primary" icon={Plus} onClick={onAdd}>Add client</Button><Button onClick={()=>onNavigate('consultations')}>Schedule</Button></>}/>
    {error&&<div role="status" className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-950"><AlertTriangle aria-hidden="true" className="mt-0.5 shrink-0 text-amber-700" size={17}/><span><strong>Partial dashboard.</strong> {error}. Unavailable metrics are not shown as zero.</span></div>}
    <section aria-label="Practice KPIs"><SectionHeader title="Practice overview" subtitle="Current operational totals from loaded source records."/><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{KPI.map(([label,key,Icon,target,source])=>{const unavailable=data.unavailable?.includes(source)||(source==='onboarding'&&!model.availability.onboarding)||(source==='attention'&&data.unavailable?.some(item=>['followups','tasks','goals','notifications'].includes(item)));return <KpiCard key={key} label={label} value={model.kpis[key]} Icon={Icon} unavailable={unavailable} onClick={()=>target==='attention'?document.getElementById('needs-attention')?.scrollIntoView({behavior:'smooth'}):onNavigate(target)}/>})}</div></section>
    <div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1.55fr)_minmax(17rem,.65fr)]"><PriorityInbox items={model.items} onNavigate={onNavigate} onOpen={onOpen}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-1"><Distribution title="Follow-up status" question="Are follow-ups being completed?" data={model.charts.followups} unavailable={data.unavailable?.includes('followups')}/><Distribution title="Goal status" question="How are active goals distributed?" data={model.charts.goals} unavailable={data.unavailable?.includes('goals')}/></div></div>
    <div className="grid gap-6 lg:grid-cols-2"><Agenda items={model.upcoming} onNavigate={onNavigate}/><RecentActivity items={model.recent}/></div>
  </div>;
}
